#include <iostream>
using namespace std;

int main() {
    float prezzo_base;
    float sconto;
    float iva;
    float prezzo_lordo;
    float prezzo_scontato;

    cout << "Inserisci in sequenza i dati sul prezzo, lo sconto e l'IVA: ";
    cin >> prezzo_base >> sconto >> iva;

    prezzo_scontato = prezzo_base - (prezzo_base * sconto / 100);
    prezzo_lordo = prezzo_scontato * (1 + iva / 100);

    cout << "Il prezzo totale e': " << prezzo_lordo << endl;

    system("pause");
}
